// ===================== CONFIG (generated by build_flow.py) =====================
const config = {
    port: 56700,
    maxRate: 20,        // max msgs/sec per bulb (LIFX recommends <= 20)
    smoothMs: 100,      // transition per colour; > 1000/maxRate so fades overlap (smoother)
    kelvin: 3500,       // colour temp used for whites / low saturation
    gamma: 1.0,         // >1 darkens mids (WLED usually already applies gamma)
    minChange: 1,       // skip updates whose RGB(W) delta is below this
    blackoutMs: 4000,   // group all-black this long -> power bulbs OFF and release them
    discoverEveryMs: 30000,     // re-find bulbs by MAC (handles DHCP changes / rejoin)
    broadcast: ['255.255.255.255', '192.168.2.255'],
    controlPixel: 24,     // mode select: black = solid, blue-dominant = starfield, other = flame
    matrixBudget: 250,          // HARD CAP: Set64 msgs/sec across all candles (2.4 GHz airtime!
                                // ~300+/s wedged the EAP787 on 2026-11-23)
    flame: {
        fps: 10,        // flame render rate (per candle) -> ~210 msgs/s for 21 candles
        flicker: 0.45,  // 0..1 flicker depth, strongest at the tip
        tipDesat: 0.35, // tip is this much less saturated (lighter) than the base colour
        baseLevel: 0.40,// base row brightness relative to the brightest row
    },
    starfield: {        // background = WLED colour per candle; random zones flash white
        rate: 20,       // flash events per second (chandelier-wide)
        minZones: 1, maxZones: 3,   // zones per event
        spread: 0.3,    // random start offset per zone (s) -> flashes may or may not overlap
        hold: 0.05,     // seconds at full white
        fade: 0.35,     // seconds to fade back
        fps: 20,        // max repaint rate per busy candle
