        {"name": "Tier3Bulb8", "mac": "d0:73:d5:81:ea:fd", "ip": "192.168.2.86", "group": "tier3", "matrix": [5, 6], "pixel": 19},
        {"name": "Tier3Bulb9", "mac": "d0:73:d5:d3:cf:91", "ip": "192.168.2.94", "group": "tier3", "matrix": [5, 6], "pixel": 20},
        {"name": "Tier3Bulb10", "mac": "d0:73:d5:d3:bb:84", "ip": "192.168.2.89", "group": "tier3", "matrix": [5, 6], "pixel": 21},
        {"name": "Tier3Bulb11", "mac": "d0:73:d5:d3:cc:8f", "ip": "192.168.2.96", "group": "tier3", "matrix": [5, 6], "pixel": 22},
        {"name": "Tier3Bulb12", "mac": "d0:73:d5:d3:b7:f8", "ip": "192.168.2.85", "group": "tier3", "matrix": [5, 6], "pixel": 23}
    ],
};
// ==============================================================================

const SOURCE = 0x44445031; // "DDP1"
const state = config.bulbs.map(b => ({
    ...b,
    key: b.mac.replace(/:/g, '').toLowerCase(),
    target: Buffer.concat([Buffer.from(b.mac.split(':').map(x => parseInt(x, 16))), Buffer.alloc(2)]),
    seen: 0, last: null, lastSent: 0, pending: null, timer: null, seq: 0, color: null, n: 0,
}));
const byKey = Object.fromEntries(state.map(s => [s.key, s]));
const groups = {};
for (const s of state) (groups[s.group] = groups[s.group] || { name: s.group, bulbs: [], released: undefined, blackSince: 0 }).bulbs.push(s);
for (const s of state) s.g = groups[s.group];

const sock = dgram.createSocket({ type: 'udp4', reuseAddr: true });
sock.on('error', e => node.warn('LIFX socket: ' + e.message));
sock.on('message', (d, rinfo) => {           // StateService (3) from discovery
    if (d.length < 36 || d.readUInt16LE(32) !== 3) return;
    const s = byKey[d.subarray(8, 14).toString('hex')];
    if (!s) return;
    if (s.ip !== rinfo.address) {
        if (s.seen) node.warn(`${s.name} moved ${s.ip} -> ${rinfo.address}`);
        s.ip = rinfo.address;
    }
    s.seen = Date.now();
});
sock.bind(0, () => { sock.setBroadcast(true); discover(); });

function header(s, type, payloadLen, tagged) {
    const p = Buffer.alloc(36 + payloadLen);
    p.writeUInt16LE(36 + payloadLen, 0);
    p.writeUInt16LE(1024 | 0x1000 | (tagged ? 0x2000 : 0), 2);
    p.writeUInt32LE(SOURCE, 4);
    if (s) s.target.copy(p, 8);
    p[22] = tagged ? 1 : 0;              // discovery wants a response; others don't
    if (s) p[23] = (s.seq = (s.seq + 1) & 0xff);
    p.writeUInt16LE(type, 32);
    return p;
}

function discover() {
    const p = header(null, 2, 0, true);   // GetService, tagged broadcast
    for (const a of config.broadcast) sock.send(p, config.port, a);
}

function setColor(s, [h, sat, bri, k], durationMs) {   // SetColor (102)
    const p = header(s, 102, 13);
    p.writeUInt16LE(h, 37); p.writeUInt16LE(sat, 39);
    p.writeUInt16LE(bri, 41); p.writeUInt16LE(k, 43);
    p.writeUInt32LE(durationMs, 45);
    return p;
}

function setPower(s, on) {                              // SetLightPower (117)
    const p = header(s, 117, 6);
    p.writeUInt16LE(on ? 65535 : 0, 36);
    p.writeUInt32LE(0, 38);
    return p;
}

function set64(s, colors, durationMs) {                 // Set64 (715): whole matrix in one message
    const p = header(s, 715, 522);
    p[36] = 0; p[37] = 1; p[38] = 0; p[39] = 0; p[40] = 0; p[41] = s.matrix[0];
    p.writeUInt32LE(durationMs, 42);
    colors.forEach((c, i) => {
        const o = 46 + i * 8;
        p.writeUInt16LE(c[0], o); p.writeUInt16LE(c[1], o + 2);
        p.writeUInt16LE(c[2], o + 4); p.writeUInt16LE(c[3], o + 6);
    });
    return p;
}

function hsv(r, g, b, w) {           // -> [hueDeg, sat 0..1, val 0..1]
    const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
    let h = 0;
    if (d) {
        if (max === r) h = ((g - b) / d) % 6;
        else if (max === g) h = (b - r) / d + 2;
        else h = (r - g) / d + 4;
        h *= 60; if (h < 0) h += 360;
    }
    let s = max ? d / max : 0;
    let v = max / 255;
    if (w) {                         // white channel desaturates and adds level
        s = max + w ? s * max / (max + w) : 0;
        v = Math.max(max, w) / 255;
    }
    return [h, s, Math.pow(v, config.gamma)];
}

const clamp = x => x < 0 ? 0 : x > 1 ? 1 : x;
function hsbk(h, s, v) {
    return [Math.round(h / 360 * 65536) % 65536, Math.round(clamp(s) * 65535), Math.round(clamp(v) * 65535), config.kelvin];
}
function toHsbk(r, g, b, w) { return hsbk(...hsv(r, g, b, w)); }

function out(s, buf) { if (s.ip) sock.send(buf, config.port, s.ip); }

function flush(s) {
    s.timer = null;
    if (!s.pending || s.g.released) { s.pending = null; return; }
    const c = s.pending; s.pending = null;
    s.last = c; s.lastSent = Date.now();
    out(s, setColor(s, toHsbk(...c), config.smoothMs));
    context.set('sent', (context.get('sent') || 0) + 1);
}

// ---------------- flame renderer (matrix bulbs, while flame mode is on) ----------------
const F = config.flame;
function renderFlame() {
    if (context.get('mode') !== 'flame') return;
    if (Date.now() - (context.get('lastFrame') || 0) > 5000) return;      // stream stopped
    const dur = Math.round(1500 / F.fps);
    for (const s of state) {
        if (!s.matrix || !s.color || s.g.released) continue;
        const [h, sat, v] = hsv(...s.color);
        if (v <= 0.01) { out(s, setColor(s, hsbk(h, sat, 0), dur)); continue; }
        // per-candle random walk + a faster "lick" component
        s.n = s.n * 0.75 + (Math.random() - 0.5) * 0.9;
        const lick = (Math.random() - 0.5) * 0.5;
        const [W, H] = s.matrix;
        const colors = [];
        for (let y = 0; y < H; y++) {
            const t = 1 - y / (H - 1);                     // 1 = tip (row 0), 0 = base
            const prof = F.baseLevel + (1 - F.baseLevel) * Math.min(1, t * 1.5) * (y === 0 ? 0.9 : 1);
            const fl = 1 + F.flicker * t * (s.n + lick * t);
            for (let x = 0; x < W; x++) {
                const jitter = 1 + F.flicker * 0.25 * (Math.random() - 0.5) * t;
                colors.push(hsbk((h + 8 * t * (Math.random() - 0.3) + 360) % 360,
                                 sat * (1 - F.tipDesat * t), v * prof * fl * jitter));
            }
        }
        if (!take()) continue;
        out(s, set64(s, colors, dur));
        context.set('sent', (context.get('sent') || 0) + 1);
    }
}

// ---------------- shared airtime budget for matrix (Set64) messages ----------------
const budget = { tokens: config.matrixBudget / 10, t: Date.now() };
function take() {
    const now = Date.now();
    budget.tokens = Math.min(config.matrixBudget / 10, budget.tokens + (now - budget.t) * config.matrixBudget / 1000);
    budget.t = now;
    if (budget.tokens >= 1) { budget.tokens -= 1; return true; }
    context.set('throttled', (context.get('throttled') || 0) + 1);
    return false;
}

// ---------------- starfield renderer ----------------
const SF = config.starfield;
for (const s of state) if (s.matrix) {
    const [w, h] = s.matrix;
    s.zones = [0];                                   // row 0 = tip (single zone)
    for (let y = 1; y < h; y++) for (let x = 0; x < w; x++) s.zones.push(y * w + x);
    s.sparks = []; s.sfLast = 0; s.sfDirty = true;
}
let nextEvent = 0;
function env(t) {
    if (t < 0) return 0;
    if (t < SF.hold) return 1;
    t -= SF.hold;
    return t < SF.fade ? Math.pow(1 - t / SF.fade, 2) : 0;
}
function renderStarfield() {
    if (context.get('mode') !== 'starfield') { nextEvent = 0; return; }
    if (Date.now() - (context.get('lastFrame') || 0) > 5000) return;      // stream stopped
    const now = Date.now() / 1000;
    const mats = state.filter(s => s.matrix && s.color && !s.g.released);
    if (!mats.length) return;
    if (!nextEvent) nextEvent = now;
    while (now >= nextEvent) {
        const k = SF.minZones + Math.floor(Math.random() * (SF.maxZones - SF.minZones + 1));
        for (let i = 0; i < k; i++) {
            const s = mats[Math.floor(Math.random() * mats.length)];
            s.sparks.push([s.zones[Math.floor(Math.random() * s.zones.length)], nextEvent + Math.random() * SF.spread]);
        }
        nextEvent += -Math.log(1 - Math.random()) / SF.rate;
    }
    for (const s of mats) {
        if (!s.sparks.length && !s.sfDirty) continue;
        if (now - s.sfLast < 1 / SF.fps) continue;
        if (!take()) continue;
        const [h, sat, v] = hsv(...s.color);
        const n = s.matrix[0] * s.matrix[1];
        const lv = new Array(n).fill(0), alive = [];
        for (const [z, st] of s.sparks) {
            lv[z] = Math.max(lv[z], env(now - st));
            if (now - st < SF.hold + SF.fade) alive.push([z, st]);
        }
        s.sparks = alive;
        const colors = lv.map(l => [Math.round(h / 360 * 65536) % 65536, Math.round(clamp(sat * (1 - l)) * 65535),
                                    Math.round(clamp(v + (1 - v) * l) * 65535),
                                    Math.round(config.kelvin + (SF.flashKelvin - config.kelvin) * l)]);
        out(s, set64(s, colors, Math.round(1000 / SF.fps)));
        context.set('sent', (context.get('sent') || 0) + 1);
        s.sfDirty = alive.length > 0;
        s.sfLast = now;
    }
}

const discTimer = setInterval(discover, config.discoverEveryMs);
const sfTimer = setInterval(renderStarfield, 10);
const flameTimer = setInterval(renderFlame, 1000 / F.fps);
// Safety net: while streaming, re-assert power on groups we control (lost UDP, rejoined bulbs)
const powerTimer = setInterval(() => {
    if (Date.now() - (context.get('lastFrame') || 0) > 5000) return;
    for (const g of Object.values(groups)) if (g.released === false) g.bulbs.forEach(s => out(s, setPower(s, true)));
}, 10000);

context.set('config', config);
context.set('state', state);
context.set('groups', groups);
context.set('helpers', { setPower, flush, out });
context.set('closer', () => {
    clearInterval(discTimer); clearInterval(flameTimer); clearInterval(powerTimer); clearInterval(sfTimer);
    state.forEach(s => s.timer && clearTimeout(s.timer));
    try { sock.close(); } catch (e) {}
});

