// Builds a single DDP packet so you can test without a DDP source.
// msg.payload = [r,g,b] (all pixels) or [[r,g,b], [r,g,b], ...] (per pixel)
const n = 25;   // includes control pixel   // pixel count to generate
const p = msg.payload;
const px = Array.isArray(p[0]) ? p : Array(n).fill(p);
const data = Buffer.from(px.flat());
const hdr = Buffer.alloc(10);
hdr[0] = 0x41; hdr[2] = 0x0B; hdr[3] = 1;   // v1+push, RGB8, display 1
hdr.writeUInt16BE(data.length, 8);
return { payload: Buffer.concat([hdr, data]), ip: 'test' };
